            realRouter,
            abi.encodeWithSignature("factory()"),
            abi.encode(mockFactory)
        );
        vm.mockCall(
            realRouter,
            abi.encodeWithSignature("WETH()"),
            abi.encode(mockWETH)
        );
        vm.mockCall(
            mockFactory,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(mockPair)
        );

        // Deploy token
        token = new PULIINU(
            0,                    // deadBlocks
            1,                    // buy liquidity fee
            1,                    // buy marketing fee
            1,                    // sell liquidity fee
            1,                    // sell marketing fee
            payable(marketingWallet),
            1000 * DECIMALS,      // _supply
            100 * DECIMALS,       // numTokens
            100 * DECIMALS,       // maxWallet
            100 * DECIMALS,       // maxBuy
            100 * DECIMALS        // maxSell
        );
    }

    function testFeeManipulation() public {
        // Set buy fees to excessive levels (each component 10% -> total 40%)
        token.setBuyFee(
            uint16(EXCESSIVE_FEE), 
            uint16(EXCESSIVE_FEE), 
            uint16(EXCESSIVE_FEE), 
            uint16(EXCESSIVE_FEE)
        );

        // Set sell fees to excessive levels
        token.setSellFee(
            uint16(EXCESSIVE_FEE), 
            uint16(EXCESSIVE_FEE), 
            uint16(EXCESSIVE_FEE), 
            uint16(EXCESSIVE_FEE)
        );

        // Read updated fee structures (ignore unused components to prevent warnings)
        (uint16 liqBuy, uint16 marketBuy,,) = token.buyFee();
        (uint16 liqSell, uint16 marketSell,,) = token.sellFee();

        // Verify fees were set to excessive values
        assertEq(liqBuy, EXCESSIVE_FEE, "Buy liquidity fee manipulation");
        assertEq(marketBuy, EXCESSIVE_FEE, "Buy marketing fee manipulation");
        assertEq(liqSell, EXCESSIVE_FEE, "Sell liquidity fee manipulation");
        assertEq(marketSell, EXCESSIVE_FEE, "Sell marketing fee manipulation");
    }
}
